import React, { useState, useEffect } from 'react';

const Autocomplete = ({
  data,
  onSelect,
  placeholder = 'Type to search...',
  minLength = 2
}) => {
  const [terms, setTerms] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(null);

  useEffect(() => {
    const debouncedSearch = setTimeout(() => {
      const filteredData = data.filter((item) => {
        return item.toLowerCase().includes(terms.toLowerCase());
      });
      setSuggestions(filteredData);
    }, 300);

    return () => clearTimeout(debouncedSearch);
  }, [terms, data]);

  const handleClick = (item) => {
    onSelect(item);
    setTerms('');
  };

  const handleInput = (event) => {
    setTerms(event.target.value);
  };

  const handleKeyDown = (event) => {
    if (event.key === 'ArrowDown' && activeSuggestionIndex !== null) {
      setActiveSuggestionIndex((prevIndex) => prevIndex + 1);
    } else if (event.key === 'ArrowUp' && activeSuggestionIndex !== null) {
      setActiveSuggestionIndex((prevIndex) => prevIndex - 1);
    } else if (event.key === 'Enter') {
      if (activeSuggestionIndex !== null) {
        handleClick(suggestions[activeSuggestionIndex]);
      }
    }
  };

  return (
    <div className="autocomplete">
      <input
        type="text"
        value={terms}
        onChange={handleInput}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
