```csharp
using System;
using System.Net;
using System.Net.Http;
using System.Text;

namespace MyHttpServer
{
    class Program
    {
        static void Main(string[] args)
        {
            // Création du serveur HTTP
            HttpListener listener = new HttpListener();
            listener.Prefixes.Add("http://localhost:8080/"); // ou "http://+/:8080/"
            listener.Start();

            Console.WriteLine("Server started. Listening on http://localhost:8080/");

            while (true)
            {
                HttpListenerContext context = listener.GetContext();
                HttpListenerRequest request = context.Request;

                // Traitement de la requête
                if (request.Url.AbsolutePath == "/hello")
                {
                    string responseBody = "<html><body>Hello</body></html>";
                    byte[] responseBytes = Encoding.ASCII.GetBytes(responseBody);
                    HttpListenerResponse response = context.Response;
                    response.ContentLength64 = responseBytes.Length;
                    response.OutputStream.Write(responseBytes, 0, responseBytes.Length);
                    response.OutputStream.Close();
                }
                else
                {
                    // Réponse 404 si la requête n'est pas pour la page "hello"
                    byte[] responseBytes = Encoding.ASCII.GetBytes("Not found");
                    HttpListenerResponse response = context.Response;
                    response.StatusCode = 404;
                    response.ContentLength64 = responseBytes.Length;
                    response.OutputStream.Write(responseBytes, 0, responseBytes.Length);
                    response.OutputStream.Close();
                }
            }
        }
    }
}
```
Explanations :

* Nous créons un objet `HttpListener` et définissons un prefix de base pour le serveur (`http://localhost:8080/`). Cela signifie que le serveur écoutera les requêtes pour les urls qui commencent par ce prefix.
* Nous appels `Start()` pour démarrer le serveur.
* Dans la boucle infinie, nous nous assurons que le serveur est en écoute avec `GetContext()`.
* Nous examinons la requête en cours avec `request.Url.AbsolutePath` et nous vérifions si cela correspond à la page "hello" (`/hello`). Si c'est le cas, nous construisons une réponse HTML simple avec le message "Hello" et nous l'envoyons au client avec `HttpResponse`.
* Si la requête n'est pas pour la page "hello", nous envoyons une réponse 404 avec un message "Not found".

